const requests = new Map();

function checkRateLimit(ip, maxPerMinute = 60) {
  const now = Date.now();
  const history = (requests.get(ip) ?? []).filter(t => now - t < 60000);
  if (history.length >= maxPerMinute) return false;
  history.push(now);
  requests.set(ip, history);
  return true;
}

